import os,subprocess,shutil,pwd
from pathlib import Path
def run(args,timeout=35):
 return subprocess.run(args,capture_output=True,text=True,timeout=timeout)
def service(name):
 return run(['systemctl','is-active',name+'.service'],8).stdout.strip()
services=['fadego-staging','lowcost-europa','pink-iptv-backend','pink-vpn','nginx','pm2-root','postgresql@16-main']
baseline={n:service(n) for n in services}
if any(s!='active' for s in baseline.values()):raise RuntimeError('A protected service is inactive')
targets=[('root',Path('/root/.cache/pip')),('ubuntu',Path('/home/ubuntu/.cache/pip'))]
for user,p in targets:
 if not p.is_dir() or p.is_symlink():raise RuntimeError('pip cache path unexpectedly absent or linked '+user)
 if p.stat().st_uid!=pwd.getpwnam(user).pw_uid:raise RuntimeError('pip cache owner unexpected '+user)
 pdir=p.parent
 if pdir.is_symlink() or not pdir.is_dir():raise RuntimeError('Parent cache directory is symlink')
 cmd=['/usr/bin/python3','-m','pip','cache','dir'] if user=='root' else ['sudo','-n','-u',user,'/usr/bin/python3','-m','pip','cache','dir']
 v=run(cmd,25)
 if v.returncode or v.stdout.strip()!=str(p):raise RuntimeError('pip cache CLI does not match allowed home: '+user+' '+v.stderr.strip()[:150])
for process in Path('/proc').iterdir():
 if not process.name.isdigit():continue
 try:
  raw=(process/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
  if 'python3 -' in raw:continue
  if 'pip ' in raw or 'pip3 ' in raw or 'pip-compile' in raw:raise RuntimeError('pip operation active; preserve cache')
 except OSError:pass
def size(path):
 r=run(['du','-x','-s','-B1',str(path)],30)
 if r.returncode:raise RuntimeError('Cannot measure cache')
 return int(r.stdout.split()[0])
before={user:size(path) for user,path in targets}
free0=shutil.disk_usage('/').free
print('PIP_CACHE_BEFORE='+','.join(user+':'+str(sz) for user,sz in before.items()))
for user,p in targets:
 cmd=['/usr/bin/python3','-m','pip','cache','purge'] if user=='root' else ['sudo','-n','-u',user,'/usr/bin/python3','-m','pip','cache','purge']
 v=run(cmd,95)
 if v.returncode:raise RuntimeError('pip cache cleanup failed for '+user+' '+v.stderr.strip()[:160])
 print('PIP_PURGED='+user)
after={user:size(path) for user,path in targets}
print('PIP_CACHE_AFTER='+','.join(user+':'+str(sz) for user,sz in after.items()))
print('PIP_CACHE_DIR_REDUCTION_BYTES='+str(sum(before.values())-sum(after.values())))
print('DISK_FREE_GAIN_BYTES='+str(shutil.disk_usage('/').free-free0))
for name,s in baseline.items():
 if service(name)!=s:raise RuntimeError('Service changed after pip cache cleanup: '+name)
